import { DowntimeTicketMessage } from './interface/publish-downtime-ticket.interface';
import { AppLogger } from '@/common/logger/app-logger';
import { EventhubService } from '@/config/eventhub/eventhub.service';

@Injectable()
export class PublishMessageService {
  private readonly daprClient: DaprClient;

  private readonly eventhubService: EventhubService;

  public constructor(
    eventhubService: EventhubService,
    private readonly customLogger: AppLogger,
  ) {
    this.eventhubService = eventhubService;
    this.daprClient = new DaprClient({
      communicationProtocol: CommunicationProtocolEnum.HTTP,
      daprPort: process.env.DAPR_PORT,
    });
  }

  public async publishMessage(
    topic: string,
    data: ContainerMessage | DowntimeTicketMessage | string,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'publishMessage',
      service: 'PublishMessageService',
    };
    try {
      this.customLogger.debug(`Publishing ${JSON.stringify(data)}`, context);
      const { pubSubName } = this.eventhubService;
      await this.daprClient.pubsub.publish(pubSubName, topic, data);
    } catch (error) {
      this.customLogger.error(
        `Failed to publish message: ${error.message}`,
        context,
        error,
      );
    }
  }
}

/**
 * Sleep function
 * @param time number of ms to wait
 * @returns void
 */
export async function asyncSleep(time: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, time);
  });
}

