import { SubscribeResponseDto } from '@/common/subscribe/dtos/subscribe.response.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

@Injectable()
export class SubscribeMessageService {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async handleMessage(message: SubscribeResponseDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessage',
      service: 'SubscribeMessageService',
    };
    try {
      this.customLogger.debug(
        `====== Received Message ========== ${JSON.stringify(message)}`,
        context,
      );
      const plants = await this.fetchPlant();
      await this.savePlantsInRedis(plants);
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error}`,
        context,
        error.stack,
      );
    }
  }

  public async savePlantsInRedis(
    plants: Array<PlantsResponseDto>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'savePlantsInRedis',
      service: 'SubscribeMessageService',
    };
    try {
      const { redisStoreAmr, redisPlantKey } = this.redisConfigService;
      const dataToCache = {
        key: redisPlantKey,
        value: [plants],
      };

      await this.daprClient.state.save(redisStoreAmr, [dataToCache]);
    } catch (error) {
      this.customLogger.error(
        `Error saving list of plant in Redis: ${error}`,
        context,
        error.stack,
      );
    }
  }

  public async fetchPlant(): Promise<Array<PlantsResponseDto>> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/Plants`;
    const context: JobsLogContext = {
      method: 'fetchPlant',
      service: 'SubscribeMessageService',
    };

    const options =
      process.env.TOKEN === ''
        ? {}
        : { headers: { authorization: `Bearer ${process.env.TOKEN}` } };
    this.customLogger.debug('Start fetching plants', context);
    const response = await this.daprClient.invoker
      .invoke(serviceAppId, serviceMethod, HttpMethod.GET, undefined, options)
      .catch((error) =>
        this.customLogger.error('Error in fetching plants', context, error),
      );
    if (response) {
      this.customLogger.log(
        `succeed in fetching plants :${JSON.stringify(response)}`,
        context,
      );
      return response as Array<PlantsResponseDto>;
    }
    throw new Error('Invalid response from fetchPlant');
  }
}

/**
 * Default catch function that returns the error as the specified type.
 * @param error - The error caught in the try block.
 * @returns The error cast to the specified type.
 */
function defaultCatchFunction<TError>(error: Error): TError {
  return error as unknown as TError;
}

/**
 * A utility function that wraps try-catch logic in a consistent return format.
 *
 * This function can be called either with a function:
 * `asyncTryCatch(() => Promise<T>)`
 *
 * Or with an object containing `tryFn` and an optional `catchFn`:
 * `asyncTryCatch({ tryFn: () => Promise<T>, catchFn?: (err) => TError })`
 * @param optionsOrTryFunction - Either a function to execute, or an object with `tryFn` (required) and `catchFn` (optional).
 * @returns A tuple: [result or undefined, error or undefined].
 */
export async function asyncTryCatch<T, TError = Error>(
  optionsOrTryFunction:
    | (() => Promise<T>)
    | {
        /**
         * The function to attempt execution of.
         */
        tryFn: () => Promise<T>;

        /**
         * Optional catch handler to customize the returned error.
         */
        catchFn?: (error: Error) => Promise<TError> | TError;
      },
): Promise<[T | undefined, TError | undefined]> {
  try {
    if (typeof optionsOrTryFunction === 'function') {
      return [await optionsOrTryFunction(), undefined];
    }

    return [await optionsOrTryFunction.tryFn(), undefined];
  } catch (error_) {
    const error = error_ instanceof Error ? error_ : new Error(String(error_));
    const catchFunction =
      typeof optionsOrTryFunction !== 'function' && optionsOrTryFunction.catchFn
        ? optionsOrTryFunction.catchFn
        : defaultCatchFunction;

    return [undefined, await catchFunction(error)];
  }
}

/**
 * Wraps a promise with a timeout. If the promise does not resolve or reject
 * within the specified time, the returned promise is rejected with a timeout error.
 * @template T - The resolved type of the input promise.
 * @param promise - The promise to wrap with a timeout.
 * @param ms - Timeout duration in milliseconds.
 * @returns A promise that resolves with the input promise or rejects if the timeout is exceeded.
 * @throws {Error} Throws "Operation timed out" if the promise does not settle within the given time.
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout>;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => reject(new Error('Operation timed out')), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() =>
    clearTimeout(timeoutId),
  );
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class AppConfigInitialConfigService implements OnModuleInit {
  public constructor(private readonly configService: ConfigService) {}

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  public get appConfigCachingTtl(): number {
    return this.configService.get<number>('appConfigCachingTtl') ?? 20_000;
  }

  public get appConfigEndpoint(): string {
    return this.configService.get<string>('appConfigEndpoint') ?? '';
  }

  private checkConfiguration(): void {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'AppConfigInitialConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [{ key: 'appConfigEndpoint', value: this.appConfigEndpoint }];

    /*
     * Check mandatory fields
     */
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        Logger.error(`Missing configuration value for ${config.key}`, context);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
  }
}

