import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class DaprConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get bindingContainer(): string {
    return this.configService.get<string>('bindingContainer') ?? '';
  }

  public get bindingPlantConfig(): string {
    return this.configService.get<string>('bindingPlantConfig') ?? '';
  }

  public get bindingResource(): string {
    return this.configService.get<string>('bindingResource') ?? '';
  }

  public get bindingNonTrsTicket(): string {
    return this.configService.get<string>('bindingNonTrsTicket') ?? '';
  }

  public get bindingNonTrsCause(): string {
    return this.configService.get<string>('bindingNonTrsCause') ?? '';
  }

  public get bindingFamily(): string {
    return this.configService.get<string>('bindingFamily') ?? '';
  }

  public get plantHierarchyApiAppId(): string {
    return this.configService.get<string>('plantHierarchyApiAppId') ?? '';
  }

  public onModuleInit(): void {
    this.validateConfiguration();
  }

  private validateConfiguration(): void {
    const context: JobsLogContext = {
      method: 'validateConfiguration',
      service: 'DaprConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'bindingContainer', value: this.bindingContainer },
      { key: 'bindingPlantConfig', value: this.bindingPlantConfig },
      { key: 'bindingResource', value: this.bindingResource },
      { key: 'bindingNonTrsTicket', value: this.bindingNonTrsTicket },
      { key: 'bindingNonTrsCause', value: this.bindingNonTrsCause },
      { key: 'bindingFamily', value: this.bindingFamily },
      { key: 'plantHierarchyApiAppId', value: this.plantHierarchyApiAppId },
    ];

    const missingConfigs = requiredConfigs.filter(
      (config) => config.value === undefined,
    );

    if (missingConfigs.length > 0) {
      for (const config of missingConfigs) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
      }
      throw new Error(
        'Configuration error: Some required configurations are not set.',
      );
    }
  }
}

