    private readonly appConfigService: AppConfigService,
  ) {}

  public async prodDiLogLevel(): Promise<LogLevel> {
    let value = this.configService.get<string>('prodDiLogLevel') as LogLevel;

    if (value) {
      Logger.warn(`'prodDiLogLevel' was read from environment variable`);
    } else {
      value = (await this.appConfigService.getConfigurationValue(
        'PROD_DI_LOG_LEVEL',
      )) as LogLevel;
    }

    return value ?? '';
  }

