    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprServiceApi.name, userId };
  }

  private plantList: Array<PlantsResponseDto> = [];

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly mutexManagerService: MutexManagerService,
    private readonly redisConfigService: RedisConfigService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
  }

  public async initializePlant(): Promise<void> {
    const context = DaprServiceApi.createLogContext('initializePlant');

    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStoreAmr,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plants List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  private async acquireIngestionLock(
    lockKey: string,
    plant: number,
    context: JobsLogContext,
  ): Promise<(() => void) | undefined> {
    const operationInfo = {
      name: 'Acquire lock for ingestion tracking',
      srcLocation: 'processMessage',
    };

    return execAndLog(
      this.customLogger,
      context,
      () =>
        acquireLockManagerWithTimeout(
          this.customLogger,
          context,
          this.mutexManagerService,
          lockKey,
        ),
      operationInfo,
      { lockKey, plant },
    );
  }

  private async trackIngestionEvent(
    ingestionEventTracking: IngestionEventTrackingDTO,
    context: JobsLogContext,
    plant: number,
    lockKey: string,
  ): Promise<boolean> {
    const operationDetails = { lockKey, plant };

    const valid = await execAndLog(
      this.customLogger,
      context,
      () =>
        validateAndTrackChanges(
          this.customLogger,
          this.ingestionEventTrackingService,
          ingestionEventTracking,
        ),
      {
        name: 'Validate and track ingestionEventTracking',
        srcLocation: 'processMessage',
      },
      operationDetails,
    );

    if (!valid) return false;

    await execAndLog(
      this.customLogger,
      context,
      () =>
        this.ingestionEventTrackingService.upsertCache(ingestionEventTracking),
      {
        name: 'Upsert ingestionEventTracking cache',
        srcLocation: 'processMessage',
      },
      operationDetails,
    );

    return true;
  }

  private async processMessage(
    message: RedisMessage,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    const { mappedData, destination, operation } = message;
    const plant = mappedData?.plant;
    const context = DaprServiceApi.createLogContext('processMessage', plant);
    this.customLogger.debug(
      `============== ${sequenceNumber} start processing message =======================`,
      context,
    );
    try {
      if (!operation) return;

      // If (operation !== 'r' && ingestionEventTracking) {
      //   Const lockKey = ingestionEventTracking.hashKey;
      //   This.customLogger.log(`Acquiring lock for key ${lockKey}`, context);

      //   Const release = await this.acquireIngestionLock(
      //     LockKey,
      //     Plant,
      //     Context,
      //   );
      //   If (!release) {
      //     This.customLogger.error(
      //       `Error: Failed to acquire lock for ${lockKey}, skipping ingestion tracking.`,
      //       Context,
      //     );
      //     Return;
      //   }

      //   Try {
      //     Const success = await this.trackIngestionEvent(
      //       IngestionEventTracking,
      //       Context,
      //       Plant,
      //       LockKey,
      //     );
      //     If (!success) return;
      //   } finally {
      //     This.customLogger.log(`Releasing lock for ${lockKey}`, context);
      //     Release();
      //   }
      // }
      await emitSqlEvent(
        context,
        this.customLogger,
        this.eventEmitter,
        destination,
        mappedData,
        operation,
      );
      this.customLogger.debug(
        `============== ${sequenceNumber} After Emit event =======================`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @param sequenceNumber - The sequence number of the message
   * @returns Start the dapr server
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const context = DaprServiceApi.createLogContext('handleMessage');
    try {
      if (
        !checkPayloadConsistency(
          this.customLogger,
          context,
          record,
          this.mappingService,
        )
      )
        return;

      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable) return;

      const { mappedData, destination, ingestionEventTracking } =
        this.mappingService.mapData(sourceTable, record, this.plantList);
      // Check first if there is two table source in the mapping system
      // Fifo check
      this.customLogger.debug(
        `Mapped Data:${JSON.stringify(mappedData)}`,
        context,
      );
      if (!checkPlantConsistency(this.customLogger, mappedData, this.plantList))
        return;

      const newRecord = {
        destination,
        ingestionEventTracking,
        mappedData,
        operation,
        sourceTable,
      };
      await this.processMessage(newRecord, sequenceNumber);
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
    } finally {
      if (record) {
        await execAndLog(
          this.customLogger,
          context,
          async () => {},
          {
            name: 'handleMessage function runtime',
            srcLocation: 'handleMessage',
          },
          {
            record,
          },
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Controller, Post, Req } from '@nestjs/common';
import { Request } from 'express';
import { DaprServiceApi } from './dapr-api-version.service';
import { AppLogger } from '@/common/logger/app-logger';
import { MappingService } from '@/common/mapping/service/mapping.service';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { DaprService } from '@/dapr/dapr.service';
import { filterMaskNonTrsTicket } from '@/helpers/masks/filter-mask-non-trs-ticket';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';

// Environment variables
const bindings = {
  container: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_HU_DTL_CONTENT,
  family: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_FAMILY,
  nonTrsCause: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_NON_TRS_CAUSE,
  nonTrsTicket: process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_NON_TRS_TICKET,
  plantConfig:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_CONFIG_SERVER_PROD_DI,
  resource: process.env.INPUT_BINDINGS_CPT_FAURECIA_DBO_PLC_CONFIG_PROD_DI,
  topicPlants: process.env.TOPIC_PLANTS,
};

@Controller('')
export class DaprController {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprService.name, userId };
  }

  public constructor(
    private readonly eventhubSdkConfigService: EventhubSdkConfigService,
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly daprServiceApi: DaprServiceApi,
    private readonly mappingService: MappingService,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic topic name for telemetry
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const startTime = Date.now();
    const event = request.body;
    const plantCode =
      event?.S_SITE || event?.SITE || event?.S_PLANT || event?.PLANT;

    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      const result = await this.daprService.handleMessage(event);
      const duration = Date.now() - startTime;
      if (result.processed) {
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
      }
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.container)
  public async receiveEventContainer(@Req() request: Request): Promise<string> {
    const sequenceNumber =
      request.headers['x-opt-sequence-number'] ||
      (request.headers['X-Opt-Sequence-Number'] as string);

    const containerMessage = request.body;

    const context = DaprController.createLogContext(
      'receiveEventContainer',
      containerMessage.PLANT,
    );
    this.customLogger.debug(
      `============== ${sequenceNumber} Start ${containerMessage?.PLANT} container id  ${containerMessage?.HU_CODE}  =======================`,
      context,
    );
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    if (
      !checkPayloadConsistency(
        this.customLogger,
        context,
        containerMessage,
        this.mappingService,
      )
    ) {
      return 'NOK PAYLOAD';
    }
    return this.processStandardEvent(
      request,
      'receiveEventContainer',
      'container',
    );
  }

  @Post(bindings.resource)
  public async receiveEventResource(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventResource',
      'resource',
    );
  }

  @Post(bindings.plantConfig)
  public async receiveEventPlantConfig(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventPlantConfig',
      'plant-config',
    );
  }

  @Post(bindings.family)
  public async receiveEventFamily(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(request, 'receiveEventFamily', 'family');
  }

  @Post(bindings.nonTrsTicket)
  public async receiveEventNonTrsTicket(
    @Req() request: Request,
  ): Promise<string> {
    const sequenceNumber =
      request.headers['x-opt-sequence-number'] ||
      (request.headers['X-Opt-Sequence-Number'] as string);

    const context = DaprController.createLogContext('receiveEventNonTrsTicket');
    const nonTrsTicketMessage = request.body;
    this.customLogger.debug(
      `============== ${sequenceNumber} Start ${nonTrsTicketMessage?.PLANT} Ticket ${nonTrsTicketMessage?.TICKET}  =======================`,
      context,
    );
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    if (
      !checkPayloadConsistency(
        this.customLogger,
        context,
        nonTrsTicketMessage,
        this.mappingService,
      )
    ) {
      return 'NOK PAYLOAD';
    }

    const maskedNonTrsTicketMessage =
      filterMaskNonTrsTicket(nonTrsTicketMessage);
    await this.daprService.handleMessage(maskedNonTrsTicketMessage);
    this.customLogger.debug(
      `============== ${sequenceNumber} End ${nonTrsTicketMessage?.PLANT} Ticket ${nonTrsTicketMessage?.TICKET} =======================`,
      context,
    );
    return 'OK';
  }

  @Post(bindings.nonTrsCause)
  public async receiveEventNonTrsCause(
    @Req() request: Request,
  ): Promise<string> {
    const nonTrsCauseMessage = request.body;
    const context = DaprController.createLogContext(
      'receiveEventNonTrsCause',
      nonTrsCauseMessage.PLANT,
    );
    if (
      !checkPayloadConsistency(
        this.customLogger,
        context,
        nonTrsCauseMessage,
        this.mappingService,
      )
    ) {
      return 'NOK PAYLOAD';
    }

    const causeFamilyAssignMessage = {
      ...nonTrsCauseMessage,
      __source_table: 'cause_family_assign',
    };

    await Promise.all([
      this.daprService.handleMessage(nonTrsCauseMessage),
      this.daprService.handleMessage(causeFamilyAssignMessage),
    ]);

    return 'OK';
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprController.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      await this.daprServiceApi.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

