@Injectable()
export class EventHubSdkContainerService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkContainerService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
    private readonly mappingService: MappingService,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context = EventHubSdkContainerService.createLogContext('initialize');

    try {
      // Check if we should skip initialization
      const useEventhubSDK = await this.configService.useEventhubSDK();

      if (!useEventhubSDK) {
        this.logger.warn(
          `[Container] Skipping EventHub SDK initialization - useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }
      this.logger.log('Initializing  container EventHub service', context);

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getContainerConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();

      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
          );
        },
      };

      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.containerCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubContainerEnhancedService',
          topicName: 'container',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced container EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced container EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkContainerService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced container EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup: this.configService.containerConsumerGroup,
            eventHubName: this.configService.containerEventHubName,
            eventHubNamespace: this.configService.containerEventHubNamespace,
            checkpointInterval: this.configService.containerCheckpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubContainerEnhancedService',
          this.logger,
        );
        this.subscription = null;
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced container EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced container EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to container with validation and masking
   * @returns MessageProcessor configured for container  processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);
        const duration = Date.now() - startTime;
        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkContainerService.createLogContext('validateMessage'),
            message,
            this.mappingService,
          )
        ) {
          // Track invalid payload

          telemetryMetrics.trackEventProcessingDuration(
            duration,
            PROCESSING_STATUS.INVALID,
            plantCode,
            'container',
            partitionId,
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.INVALID,
            plantCode,
            'container',
            partitionId,
          );
          return undefined;
        }

        await this.daprService.handleMessage(message, sequenceNumber);
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          plantCode,
          'container',
          partitionId,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          plantCode,
          'container',
          partitionId,
        );
        return { status: 'processed', plantCode };
      },
    };
  }
}

import { Subscription } from '@azure/event-hubs';
import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { MappingService } from '@/common/mapping/service/mapping.service';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { DaprServiceApi } from '@/dapr/dapr-api-version.service';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import {
  PartitionInfo,
  performFinalCheckpoints,
} from '@/helpers/eventhub-functions/checkpoint';
import {
  EventHubClients,
  initializeEventHub,
  cleanupEventHub,
} from '@/helpers/eventhub-functions/initialization';
import {
  MessageProcessor,
  EnhancedMessageProcessor,
  ProcessingResult,
} from '@/helpers/eventhub-functions/message-processing';
import {
  createShutdownState,
  ShutdownState,
} from '@/helpers/eventhub-functions/shutdown';
import {
  subscribeToEventHub,
  unsubscribeFromEventHub,
} from '@/helpers/eventhub-functions/subscription';
import { filterMaskNonTrsTicket } from '@/helpers/masks/filter-mask-non-trs-ticket';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';

@Injectable()
export class EventHubSdkNontrsTicketService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkNontrsTicketService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
    private readonly mappingService: MappingService,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context =
      EventHubSdkNontrsTicketService.createLogContext('initialize');

    try {
      // Check if we should skip initialization
      const useEventhubSDK = await this.configService.useEventhubSDK();

      if (!useEventhubSDK) {
        this.logger.warn(
          `[Non-TRS Ticket] Skipping EventHub SDK initialization - useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }
      this.logger.log('Initializing  Non-TRS Ticket EventHub service', context);

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getNonTrsTicketConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();

      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
          );
        },
      };

      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.checkpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubNontrsTicketEnhancedService',
          topicName: 'nonTrsTicket',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced Non-TRS Ticket EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced Non-TRS Ticket EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkNontrsTicketService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced Non-TRS Ticket EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup: this.configService.consumerGroup,
            eventHubName: this.configService.eventHubName,
            eventHubNamespace: this.configService.eventHubNamespace,
            checkpointInterval: this.configService.checkpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubNontrsTicketEnhancedService',
          this.logger,
        );
        this.subscription = null;
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced Non-TRS Ticket EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced Non-TRS Ticket EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to Non-TRS Ticket with validation and masking
   * @returns MessageProcessor configured for Non-TRS Ticket processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);
        const duration = Date.now() - startTime;
        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkNontrsTicketService.createLogContext('validateMessage'),
            message,
            this.mappingService,
          )
        ) {
          telemetryMetrics.trackEventProcessingDuration(
            duration,
            PROCESSING_STATUS.INVALID,
            plantCode,
            'nonTrsTicket',
            partitionId,
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.INVALID,
            plantCode,
            'nonTrsTicket',
            partitionId,
          );
          return undefined;
        }

        const maskedNonTrsTicketMessage = filterMaskNonTrsTicket(message);
        await this.daprService.handleMessage(
          maskedNonTrsTicketMessage,
          sequenceNumber,
        );
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          plantCode,
          'nonTrsTicket',
          partitionId,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          plantCode,
          'nonTrsTicket',
          partitionId,
        );
        return { status: 'processed', plantCode };
      },
    };
  }
}

