/**
 * Update the cache of Queue
 * @param logger Application logger
 * @param daprClient used to move to dead letter queue
 * @param redisStoreNameAmr - Redis store name for state call (AMR)
 * @param services services
 * @param services.mappingService Mapping service to transform payload
 * @param services.serviceMutexes mutex register
 * @param inMemoryQueue inMemory queue
 * @param processingQueue Process queue to check if it is processing
 * @param plantList list of plants
 * @param data input data
 * @param data.key Key of the queue
 * @param data.operation Operation
 * @param data.record Record
 * @param data.sourceTable Source Table
 * @returns void
 */
export async function appendAndSaveToCacheQueue(
  logger: AppLogger,
  daprClient: DaprClient,
  redisStoreNameAmr: string,
  services: {
    mappingService: MappingService;
    serviceMutexes: Record<string, Mutex>;
  },
  inMemoryQueue: Record<string, Array<RedisMessage>>,
  processingQueue: Record<string, boolean>,
  plantList: Array<PlantsResponseDto>,
  data: {
    key: string;
    operation: string | undefined;
    record: CombinedDtoWithIndex;
    sourceTable: string;
  },
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    service: 'appendAndSaveToCacheQueue',
  };
  const { mappingService, serviceMutexes } = services;
  const { key, record, sourceTable, operation } = data;

  const dateFunctionStart = Date.now();
  const logOperationInfo = {
    name: '',
    srcLocation: 'appendAndSaveToCacheQueue',
  };
  const logOperationDetail = {
    key: `${key} lenght:${inMemoryQueue[key]?.length}`,
  };
  const moveToDeadLetterQueueContext: JobsLogContext = {
    method: 'moveToDeadLetterQueue',
    service: 'appendAndSaveToCacheQueue',
  };
  try {
    logger.debug(`Start appending queue ${key}`, context);
    const { mappedData, destination, ingestionEventTracking } =
      mappingService.mapData(sourceTable, record, plantList);
    // Check first if there is two table source in the mapping system
    // Fifo check
    logger.debug(`Mapped Data:${JSON.stringify(mappedData)}`, context);
    if (!checkPlantConsistency(logger, mappedData, plantList)) return;

    const newRecord = {
      destination,
      ingestionEventTracking,
      mappedData,
      operation,
      sourceTable,
    };

    logOperationInfo.name = 'Acquire lock';
    const acquireLockContext: JobsLogContext = {
      method: 'acquireLockWithTimeout',
      service: 'appendAndSaveToCacheQueue',
    };
    const release = await execAndLog(
      logger,
      acquireLockContext,
      () =>
        acquireLockWithTimeout(acquireLockContext, logger, serviceMutexes, key),
      logOperationInfo,
      logOperationDetail,
    );

    if (!release) {
      logger.error(
        `Error: Failed to acquire lock for ${key}, skipping processing.`,
        acquireLockContext,
      );
      await moveToDeadLetterQueue(
        moveToDeadLetterQueueContext,
        logger,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
      return;
    }
    try {
      logOperationInfo.name = 'Save record in queue cache';
      await execAndLog(
        logger,
        context,
        async () => inMemoryQueue[key].push(newRecord),
        logOperationInfo,
        logOperationDetail,
      );
    } catch (error) {
      logger.error(
        `Error appending and saving queue Message: ${error.message}`,
        context,
        error.stack,
      );
      await moveToDeadLetterQueue(
        moveToDeadLetterQueueContext,
        logger,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
    } finally {
      if (!processingQueue[key] && inMemoryQueue[key].length > 1) {
        const processingQueueAlias = processingQueue;
        processingQueueAlias[key] = true;
      }
      logger.debug(`End of appending and saving of queue for ${key}`, context);
      if (release) {
        if (record) {
          logOperationInfo.name = 'appendAndSaveToCacheQueue function runtime';
          await execAndLog(
            logger,
            context,
            async () => {},
            logOperationInfo,
            logOperationDetail,
            dateFunctionStart,
          );
        }
        release();
      }
    }
  } catch (error) {
    logger.error(
      `Error processing queue:${error.message}`,
      context,
      error.stack,
    );
    await moveToDeadLetterQueue(
      moveToDeadLetterQueueContext,
      logger,
      redisStoreNameAmr,
      daprClient,
      key,
      record,
      MESSAGE_ACTION.APPEND,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { DaprClient } from 'dapr-client';
import { KeyValueType } from 'dapr-client/types/KeyValue.type';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';

/**
 * Update the cache with FIFO principle
 * @param logger - Application logger
 * @param daprClient - Dapr client for State call
 * @param redisStoreNameAmr - Redis store name for state call (AMR)
 * @param key - The cache key
 * @param currentState - The current state
 * @param newRecord - The new record to add to the cache
 * @param newRecord.mappedData - The mapped data
 * @param newRecord.keysValue - The keys value
 * @param newRecord.destination - The destination
 * @param newRecord.sourceTable - The source table
 * @returns void
 */
export async function appendAndSaveToCache(
  logger: AppLogger,
  daprClient: DaprClient,
  redisStoreNameAmr: string,
  key: string,
  currentState: string | KeyValueType,
  newRecord: {
    destination: string;
    keysValue: string;
    mappedData: MappedOutput;
    sourceTable: string;
  },
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCache',
    service: 'appendAndSaveToCache',
  };
  try {
    const oldCachedData = currentState.valueOf()
      ? Object.values(currentState.valueOf())
      : [];
    const dataToCache = {
      key,
      value: [...oldCachedData, newRecord],
    };

    if (currentState.valueOf()) {
      logger.debug(`Updating state ${key} `, context);
    } else {
      logger.debug(
        `State ${key} doesn't exist caching ${JSON.stringify(dataToCache)}`,
        context,
      );
    }

    // Store the data in redis using FIFO principe
    // RedisStoreName is ACR
    // RedisStoreNameAmr is AMR

    await execAndLog(
      logger,
      context,
      () => daprClient.state.save(redisStoreNameAmr, [dataToCache]),
      {
        name: 'Save state record in cache',
        srcLocation: 'appendAndSaveToCache',
      },
      {
        key,
      },
    );
  } catch (error) {
    logger.error(
      `Failed to append and save to cache ${key}: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import * as fs from 'node:fs/promises';
import * as path from 'node:path/posix';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';
/**
 * Load queue data from backup files (used at container startup)
 * @param logger Application logger
 * @param queueBackupBasePath queue backup base path
 * @param microServiceName microservice name
 * @param inMemoryQueue load data into memory
 * @param queue queue name
 */
async function loadQueueFromFile(
  logger: AppLogger,
  queueBackupBasePath: string,
  microServiceName: string,
  inMemoryQueue: Record<string, Array<RedisMessage>>,
  queue: string,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'loadQueueFromFile',
    service: 'loadQueueFromFileShare',
  };
  try {
    logger.debug(`Loading queue from files for queue: ${queue}`, context);

    // Construct the folder path for the backup files
    const folderPath = path.join(queueBackupBasePath, microServiceName);

    try {
      await fs.access(folderPath);
    } catch (error) {
      logger.error(`Directory does not exist: ${folderPath}${error}`, context);
      return;
    }

    const files = await fs.readdir(folderPath);

    // Filter for files that match the queue naming pattern
    const queueFiles = files.filter((file) => {
      return file.startsWith(`queue-${queue}`);
    });
    const loadedData: Array<RedisMessage> = [];

    // Load and parse each file that matches the queue pattern
    const fileContents = await Promise.all(
      queueFiles.map(async (file) => {
        const filePath = path.join(folderPath, file);
        const fileContent = await fs.readFile(filePath, 'utf8');
        return JSON.parse(fileContent) as Array<RedisMessage>;
      }),
    );

    // Ensure the data is for the correct queue and append it to loadedData
    for (const parsedData of fileContents) {
      loadedData.push(...parsedData);
    }

    // If data is loaded, add it to the in-memory queue
    if (loadedData.length > 0) {
      const updatedQueue = { ...inMemoryQueue, [queue]: loadedData };
      Object.assign(inMemoryQueue, updatedQueue);
      logger.log(
        `Successfully loaded ${loadedData.length} messages into the in-memory queue.`,
        context,
      );

      // Delete the processed files after successfully loading the data
      await Promise.all(
        queueFiles.map(async (file) => {
          const filePath = path.join(folderPath, file);
          await fs.unlink(filePath); // Delete the file
          logger.debug(`Deleted file: ${filePath}`, context);
        }),
      );
    } else {
      logger.log(`No data found for queue: ${queue}`, context);
    }
  } catch (error) {
    logger.error(
      `Error loading queue from files for queue ${queue}: ${error.message}`,
      context,
      error.stack,
    );
  }
}
/**
 * Load queue data from redis (used at container starting)
 * @param logger Application logger
 * @param queueBackupBasePath queue backup base path
 * @param microServiceName micro service name
 * @param inMemoryQueue load data in memory
 */
export async function loadQueuesFromFileShare(
  logger: AppLogger,
  queueBackupBasePath: string,
  microServiceName: string,
  inMemoryQueue: Record<string, Array<RedisMessage>>,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'loadQueuesFromFileShare',
    service: 'loadQueueFromFileShare',
  };
  logger.debug('Initialize Queue List', context);

  let promiseChain = Promise.resolve();

  for (const queue of Object.keys(inMemoryQueue)) {
    promiseChain = promiseChain.then(() =>
      loadQueueFromFile(
        logger,
        queueBackupBasePath,
        microServiceName,
        inMemoryQueue,
        queue,
      ),
    );
  }

  await promiseChain;
}

import { JobsLogContext } from '@mesx/common-lib';
import { DaprClient } from 'dapr-client';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { MESSAGE_ACTION } from '@/dapr/interface/enum-message-action.interface';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';

/**
 * Move message to dead letter queue
 * @param context JobsLogContext
 * @param logger ApplicationLogger
 * @param redisStoreAmr Redis store name (AMR)
 * @param daprClient DAPR Client for state call
 * @param key The key associated with the message
 * @param message The message to move
 * @param action The action to implement
 */
export async function moveToDeadLetterQueue(
  context: JobsLogContext,
  logger: AppLogger,
  redisStoreAmr: string,
  daprClient: DaprClient,
  key: string,
  message: CombinedDtoWithIndex | RedisMessage,
  action: MESSAGE_ACTION,
): Promise<void> {
  try {
    const deadLetterQueueKey = `${key}-dead-letter-${action}`;
    const logOperationInfo = {
      name: '',
      srcLocation: 'moveToDeadLetterQueue',
    };
    const logOperationDetail = {
      key,
    };
    logOperationInfo.name = 'Get state';
    const currentState = await execAndLog(
      logger,
      context,
      () => daprClient.state.get(redisStoreAmr, deadLetterQueueKey),
      logOperationInfo,
      logOperationDetail,
    );

    const oldCachedData = currentState.valueOf()
      ? Object.values(currentState.valueOf())
      : [];

    const dataToCache = {
      key: deadLetterQueueKey,
      value: [...oldCachedData, message],
    };

    logger.error(
      `Moving message for ${key} to dead letter queue: ${JSON.stringify(
        message,
      )}`,
      context,
    );

    logOperationInfo.name = 'Save state';

    await execAndLog(
      logger,
      context,
      () => daprClient.state.save(redisStoreAmr, [dataToCache]),
      logOperationInfo,
      logOperationDetail,
    );
  } catch (error) {
    logger.error(
      `Failed to move message for ${key} to dead letter queue: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Mutex } from 'async-mutex';
import { DaprClient } from 'dapr-client';
import { acquireLockWithTimeout } from '../locks/acquire-lock';
import { moveToDeadLetterQueue } from './move-to-dead-letter-queue';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MESSAGE_ACTION } from '@/dapr/interface/enum-message-action.interface';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';

/**
 * Remove the message Queue
 * @param logger Application logger
 * @param serviceMutexes mutex register
 * @param daprClient dapr client
 * @param queue queue input structure
 * @param queue.redisStoreNameAmr store name for state call (AMR)
 * @param queue.inMemoryQueue in memory queue
 * @param queue.processingQueue in memory processing queue
 * @param queue.queueKey queue key where to remove the record
 * @param message message to remove
 * @returns void
 */
export async function removeMessageQueue(
  logger: AppLogger,
  serviceMutexes: Record<string, Mutex>,
  daprClient: DaprClient,
  queue: {
    inMemoryQueue: Record<string, Array<RedisMessage>>;
    processingQueue: Record<string, boolean>;
    queueKey: string;
    redisStoreNameAmr: string;
  },
  message: RedisMessage,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'removeMessageQueue',
    service: 'removeMessageQueue',
  };
  const moveToDeadLetterQueueContext: JobsLogContext = {
    method: 'moveToDeadLetterQueue',
    service: 'removeMessageQueue',
  };
  const { redisStoreNameAmr, inMemoryQueue, processingQueue, queueKey } = queue;
  const logOperationInfo = {
    name: '',
    srcLocation: 'removeMessageQueue',
  };
  const logOperationDetail = {
    queueKey: `${queueKey} lenght:${inMemoryQueue[queueKey]?.length}`,
  };
  const acquireLockContext: JobsLogContext = {
    method: 'acquireLockWithTimeout',
    service: 'removeMessageQueue',
  };

  logOperationInfo.name = 'Acquire lock';
  const release = await execAndLog(
    logger,
    context,
    () =>
      acquireLockWithTimeout(
        acquireLockContext,
        logger,
        serviceMutexes,
        queueKey,
      ),
    logOperationInfo,
    logOperationDetail,
  );

  if (!release) {
    logger.warn(
      `Failed to acquire priority lock for removing queue ${queueKey}, skipping.`,
      acquireLockContext,
    );
    await moveToDeadLetterQueue(
      moveToDeadLetterQueueContext,
      logger,
      redisStoreNameAmr,
      daprClient,
      queueKey,
      message,
      MESSAGE_ACTION.REMOVE,
    );
    return;
  }

  try {
    // Retrieve the Redis queue for this binding
    await execAndLog(
      logger,
      context,
      async () => {
        inMemoryQueue[queueKey].shift();
        const processingQueueAlias = processingQueue;
        processingQueueAlias[queueKey] = inMemoryQueue[queueKey].length > 0;
      },
      logOperationInfo,
      {
        queueSize: inMemoryQueue[queueKey].length,
        ...logOperationDetail,
      },
    );
  } catch (error) {
    logger.error(
      `Error processing Message for ${queueKey}: ${error.message}`,
      context,
      error.stack,
    );
    await moveToDeadLetterQueue(
      moveToDeadLetterQueueContext,
      logger,
      redisStoreNameAmr,
      daprClient,
      queueKey,
      message,
      MESSAGE_ACTION.REMOVE,
    );
  } finally {
    if (release) {
      release();
    }
    logger.debug(`End of removing message queue for ${queueKey}`, context);
  }
}

