    const context = ContainerService.createLogContext(
      'updateByContainerIdAndPlant',
      payload?.plant,
      String(payload?.containerId),
    );
    const { containerId, plant, ...containerData } = payload;

    const operationInfo = {
      name: 'Update Container (SQL)',
      srcLocation: 'container.u',
    };

    if (!payload) {
      this.customLogger.error(
        `Payload is empty: ${JSON.stringify(payload)}`,
        context,
      );
      return;
    }

    try {
      // Fetch only the needed fields
      const container = await this.containerRepository.findOne({
        select: ['plant', 'pickingOrderId', 'bookDate'], // Fetch only required fields
        // Since the plant is indexed, it's recommended to put it in first place for better performance
        where: { plant, containerId },
      });

      if (!container) {
        return;
      }
      const sqlStartTime = Date.now();
      const result = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.containerRepository.update(
            // Since the plant is indexed, it's recommended to put it in first place for better performance

            { plant, containerId },
            containerData,
          ),
        operationInfo,
        { containerData },
      );

      if (result.affected === 0) {
        return;
      }
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'container',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'container',
      );
      if (
        payload.bookDate !== undefined &&
        payload.bookDate !== null &&
        payload.pickingOrderId !== undefined &&
        payload.pickingOrderId !== null &&
        new Date(payload.bookDate).getTime() !==
          new Date(container.bookDate).getTime()
      ) {
        const containerMessage: ContainerMessage = {
          pickingOrderId: container.pickingOrderId,
          plant: container.plant,
        };
        await this.publishMessageService.publishMessage(
          this.eventhubService.topicContainer,
          containerMessage,
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating container: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  @OnEvent('container.r')
  public async readSnapshot(payload: Container): Promise<void> {
    const context = ContainerService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.containerId),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      const { containerId, plant, ...containerData } = payload;
      const sqlStartTime = Date.now();
      await this.containerRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let container = await transactionalEntityManager.findOne(Container, {
            where: { containerId, plant },
          });
          if (container) {
            // Update the entity's fields
            Object.assign(container, containerData);
          } else {
            // Create a new entity
            container = transactionalEntityManager.create(Container, {
              containerId,
              plant,
              ...containerData,
            });
          }
          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(container);
        },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'container',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'container',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Container: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
