export class DownTimeTicketModule {}

import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { DownTimeTicket } from '@/modules/down-time-ticket/entities/down-time-ticket.entity';

@Injectable()
export class DownTimeTicketService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: DownTimeTicketService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(DownTimeTicket)
    private readonly downTimeTicketRepository: Repository<DownTimeTicket>,
    private readonly eventhubService: EventhubService,
    private readonly publishMessageService: PublishMessageService,
    private readonly customLogger: AppLogger,
  ) {}

  private calculateDuration(startDate: Date, endDate: Date): number | null {
    const context = DownTimeTicketService.createLogContext('calculateDuration');
    try {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const durationMs = end.getTime() - start.getTime();
      return durationMs / 1000;
    } catch (error) {
      this.customLogger.error(
        'Error in calculateDuration',
        context,
        error.message,
      );
      return null;
    }
  }

  @OnEvent('downTimeTicket.c')
  private async create(payload: DownTimeTicket): Promise<void> {
    const context = DownTimeTicketService.createLogContext(
      'create',
      payload?.plant,
      String(payload?.ticket),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty s${payload}`, context);
    const operationInfo = {
      name: 'Create Downtime Ticket (SQL)',
      srcLocation: 'downTimeTicket.c',
    };
    try {
      const { ...downTimeTicket } = payload;
      if (downTimeTicket.endDate && downTimeTicket.startDate) {
        const duration = this.calculateDuration(
          downTimeTicket.startDate,
          downTimeTicket.endDate,
        );
        if (duration) {
          downTimeTicket.duration = duration;
        }
      }
      if (downTimeTicket.coMasterTicket === '---') {
        downTimeTicket.coMasterTicket = null as unknown as string;
      }
      if (!downTimeTicket.shiftCode) {
        downTimeTicket.shiftCode = 0;
      }
      const sqlStartTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => this.downTimeTicketRepository.save(downTimeTicket),
        operationInfo,
        { downTimeTicket },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );
      this.customLogger.debug(
        `This Down Time Ticket ${downTimeTicket.ticket} is inserted`,
        context,
      );
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicDowntimeTicketUpdates,
        downTimeTicket,
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('downTimeTicket.u')
  private async updateByTicketAndPlant(payload: DownTimeTicket): Promise<void> {
    const context = DownTimeTicketService.createLogContext(
      'updateByTicketAndPlant',
      payload?.plant,
      String(payload?.ticket),
    );
    const { ticket, plant } = payload;
    const operationInfo = {
      name: 'Update downtime ticket by ticket and plant (SQL)',
      srcLocation: 'downTimeTicket.u',
    };

    if (!payload)
      return this.customLogger.error(
        `payload is empty ${JSON.stringify(payload)}`,
        context,
      );

    try {
      operationInfo.name = 'Read Downtime Ticket (SQL)';

      // Fetch only necessary fields (e.g., ticket, plant, and any fields required for logic)
      const downTimeTicket = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.downTimeTicketRepository.findOne({
            select: [
              'ticket',
              'plant',
              'endDate',
              'startDate',
              'coMasterTicket',
              'shiftCode',
              'remark',
              'lockStatus',
              'lastProcessedTimestamp',
              'updatedAt',
              'nonQualityFlag',
            ], // Select necessary fields
            where: { plant, ticket },
          }),
        operationInfo,
      );
      if (!downTimeTicket) {
        await this.create(payload);
        return undefined;
      }

      // Update the entity
      const { ...downTimeTicketUpdated } = payload;
      if (downTimeTicketUpdated.endDate && downTimeTicketUpdated.startDate) {
        const duration = this.calculateDuration(
          downTimeTicketUpdated.startDate,
          downTimeTicketUpdated.endDate,
        );
        if (duration) {
          downTimeTicketUpdated.duration = duration;
        }
      }
      if (downTimeTicketUpdated.coMasterTicket === '---') {
        downTimeTicketUpdated.coMasterTicket = null as unknown as string;
      }
      if (!downTimeTicketUpdated.shiftCode) {
        downTimeTicketUpdated.shiftCode = 0;
      }
      if (!downTimeTicketUpdated.remark) {
        downTimeTicketUpdated.remark = null as unknown as string;
      }

      if (!downTimeTicketUpdated.cause1) {
        downTimeTicketUpdated.cause1 = null as unknown as string;
      }

      if (!downTimeTicketUpdated.cause2) {
        downTimeTicketUpdated.cause2 = null as unknown as string;
      }
      operationInfo.name = 'Update Downtime Ticket (SQL)';
      const sqlStartTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () =>
          this.downTimeTicketRepository.update(
            { plant, ticket },
            downTimeTicketUpdated,
          ),
        operationInfo,
        { downTimeTicketUpdated },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );

      await this.publishMessageService.publishMessage(
        this.eventhubService.topicDowntimeTicketUpdates,
        downTimeTicketUpdated,
      );

      operationInfo.name = 'Read Downtime Ticket (SQL)';
      const downTimeTicketUnlocked = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.downTimeTicketRepository.findOne({
            select: [
              'ticket',
              'plant',
              'lastProcessedTimestamp',
              'updatedAt',
              'lockStatus',
              'nonQualityFlag',
            ], // Fetch only relevant fields for lock status check
            where: { plant, ticket },
          }),
        operationInfo,
        { downTimeTicket },
      );

      // Perform the additional check on lockStatus and lastProcessedTimestamp
      if (
        downTimeTicketUnlocked !== null &&
        downTimeTicketUnlocked.lastProcessedTimestamp !== null &&
        downTimeTicketUnlocked.lastProcessedTimestamp <
          downTimeTicketUnlocked.updatedAt
      ) {
        downTimeTicketUnlocked.lockStatus = false;
        downTimeTicketUnlocked.lastProcessedTimestamp = null;
        // Update the ticket again after the lock status change
        operationInfo.name =
          'Update Downtime Ticket after lock status change (SQL)';
        await execAndLog(
          this.customLogger,
          context,
          () =>
            this.downTimeTicketRepository.update(
              { plant, ticket },
              downTimeTicketUnlocked,
            ),
          operationInfo,
          { downTimeTicketUpdated },
        );
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating Down Time Ticket: ${error.message}`,
        context,
      );
    }
    return undefined;
  }

  @OnEvent('downTimeTicket.r')
  public async readSnapshot(payload: DownTimeTicket): Promise<void> {
    const context = DownTimeTicketService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.ticket),
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    const operationInfo = {
      name: 'downtime readSnapshot (SQL)',
      srcLocation: 'downTimeTicket.r readSnapshot',
    };
    try {
      const { plant, ticket, ...downTimeTicketUpdated } = payload;
      const sqlStartTime = Date.now();
      const transactionPromise =
        this.downTimeTicketRepository.manager.transaction(
          async (transactionalEntityManager) => {
            // Find the existing entity
            if (
              downTimeTicketUpdated.endDate &&
              downTimeTicketUpdated.startDate
            ) {
              const duration = this.calculateDuration(
                downTimeTicketUpdated.startDate,
                downTimeTicketUpdated.endDate,
              );
              if (duration) {
                downTimeTicketUpdated.duration = duration;
              }
            }
            if (!downTimeTicketUpdated.shiftCode) {
              downTimeTicketUpdated.shiftCode = 0;
            }
            if (downTimeTicketUpdated.coMasterTicket === '---') {
              downTimeTicketUpdated.coMasterTicket = null as unknown as string;
            }
            if (!downTimeTicketUpdated.remark) {
              downTimeTicketUpdated.remark = null as unknown as string;
            }
            let downTimeTicket = await transactionalEntityManager.findOne(
              DownTimeTicket,
              {
                where: { plant, ticket },
              },
            );
            if (downTimeTicket) {
              // Update the entity's fields
              Object.assign(downTimeTicket, downTimeTicketUpdated);
            } else {
              // Create a new entity
              downTimeTicket = transactionalEntityManager.create(
                DownTimeTicket,
                {
                  plant,
                  ticket,
                  ...downTimeTicketUpdated,
                },
              );
            }
            // Save the entity (inserts if new, updates if existing)
            await transactionalEntityManager.save(downTimeTicket);
          },
        );
      await execAndLog(
        this.customLogger,
        context,
        () => transactionPromise,
        operationInfo,
        {
          downTimeTicketUpdated,
        },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'nonTrsTicket',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Down Time Ticket: ${error.message}`,
        context,
      );
    }
    return undefined;
  }
}

