import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { ResourceFamilyAssign } from '@/modules/resource-family-assign/resource-family-assign.entity';

@Injectable()
export class ResourceFamilyAssignService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: ResourceFamilyAssignService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(ResourceFamilyAssign)
    private readonly resourceFamilyAssignRepository: Repository<ResourceFamilyAssign>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('resourceFamilyAssign.c')
  private async create(payload: ResourceFamilyAssign): Promise<void> {
    const context = ResourceFamilyAssignService.createLogContext(
      'create',
      payload?.plant,
      String(payload?.resource),
    );
    if (!payload) {
      this.customLogger.error(`Payload is empty: ${payload}`, context);
      return;
    }

    try {
      const { family, ...resourceFamilyAssignData } = payload;
      if (!family) {
        this.customLogger.debug('missed resource family assign', context);
        return;
      }

      // Split family values and filter out any empty strings
      const familyValues = family.includes(';')
        ? family.split(';').filter((f) => f.trim() !== '')
        : [family];
      const sqlStartTime = Date.now();

      await this.resourceFamilyAssignRepository.manager.transaction(
        async (transactionalEntityManager) => {
          const savePromises = familyValues.map(async (familyValue) => {
            const newResourceFamilyAssignData = {
              family: familyValue,
              ...resourceFamilyAssignData,
            };
            await transactionalEntityManager.save(
              ResourceFamilyAssign,
              newResourceFamilyAssignData,
            );
            this.customLogger.debug(
              `Inserted Resource Family Assign with family: ${familyValue}`,
              context,
            );
          });

          await Promise.all(savePromises);
        },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
    } catch (error) {
      this.customLogger.error(
        `Error inserting or updating Resource Family Assign: ${error.message}`,
        context,
      );
    }
  }

  private async handleFamilyDeletions(
    resource: string,
    plant: number,
    familyValues: Array<string>,
    transactionalEntityManager: EntityManager,
  ): Promise<void> {
    const context = ResourceFamilyAssignService.createLogContext(
      'handleFamilyDeletions',
      plant,
      String(resource),
    );
    // Fetch existing resource family assignments for the given resource and plant
    const existingAssignments = await transactionalEntityManager.find(
      ResourceFamilyAssign,
      { where: { plant, resource } },
    );

    // Get the families from the existing assignments
    const existingFamilies = existingAssignments.map(
      (assignment) => assignment.family,
    );

    // Find families to be deleted (exist in the database but not in the payload)
    const familiesToDelete = existingFamilies.filter(
      (existingFamily) => !familyValues.includes(existingFamily),
    );

    if (familyValues.length === 0) {
      // If familyValues is empty or null, delete all entries for the given resource and plant
      await transactionalEntityManager
        .createQueryBuilder()
        .delete()
        .from(ResourceFamilyAssign)
        .where('resource = :resource', { resource })
        .andWhere('plant = :plant', { plant })
        .execute();

      this.customLogger.debug(
        `Deleted all Resource Family Assign entries for resource: ${resource}, plant: ${plant}`,
        context,
      );
    } else if (familiesToDelete.length > 0) {
      // Ensure no invalid or empty values in familiesToDelete
      const validFamiliesToDelete = familiesToDelete.filter(
        (family) => family && family.trim() !== '',
      );

      if (validFamiliesToDelete.length > 0) {
        // Use the 'IN' clause for deletion, ensuring valid family values
        await transactionalEntityManager
          .createQueryBuilder()
          .delete()
          .from(ResourceFamilyAssign)
          .where('resource = :resource', { resource })
          .andWhere('plant = :plant', { plant })
          .andWhere('family IN (:...families)', {
            families: validFamiliesToDelete,
          })
          .execute();

        for (const familyToDelete of validFamiliesToDelete) {
          this.customLogger.debug(
            `Deleted Resource Family Assign with family: ${familyToDelete}`,
            context,
          );
        }
      }
    }
  }

  @OnEvent('resourceFamilyAssign.u')
  private async updateByResourceAndFamilyAndPlant(
    payload: ResourceFamilyAssign,
  ): Promise<void> {
    const context = ResourceFamilyAssignService.createLogContext(
      'updateByResourceAndFamilyAndPlant',
      payload?.plant,
      String(payload?.resource),
    );
    if (!payload) {
      this.customLogger.error(`Payload is empty: ${payload}`, context);
      return;
    }

    const { resource, plant, family, ...resourceFamilyAssignData } = payload;

    try {
      // Check if family is null or undefined
      let familyValues: Array<string> = [];

      if (family) {
        familyValues = family.includes(';')
          ? family.split(';').filter((f) => f.trim() !== '')
          : [family];
      } // Treat null family as an empty array or adjust logic based on your needs.
      const sqlStartTime = Date.now();

      await this.resourceFamilyAssignRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Handle family deletions with the new helper function
          await this.handleFamilyDeletions(
            resource,
            plant,
            familyValues,
            transactionalEntityManager,
          );
          // Handle insertion or update of existing families
          const upsertPromises = familyValues.map(async (familyValue) => {
            if (familyValue && familyValue.trim() !== '') {
              let resourceFamilyAssign =
                await transactionalEntityManager.findOne(ResourceFamilyAssign, {
                  where: { family: familyValue, plant, resource },
                });

              if (resourceFamilyAssign) {
                // Update the entity's fields
                Object.assign(resourceFamilyAssign, resourceFamilyAssignData);
              } else {
                // Create a new entity
                resourceFamilyAssign = transactionalEntityManager.create(
                  ResourceFamilyAssign,
                  {
                    family: familyValue,
                    plant,
                    resource,
                    ...resourceFamilyAssignData,
                  },
                );
              }

              // Save the entity (inserts if new, updates if existing)
              await transactionalEntityManager.save(resourceFamilyAssign);
            }
          });

          await Promise.all(upsertPromises);
        },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Resource Family Assign: ${error.message}`,
        context,
      );
    }
  }

  @OnEvent('resourceFamilyAssign.r')
  private async readSnapshot(payload: ResourceFamilyAssign): Promise<void> {
    const context = ResourceFamilyAssignService.createLogContext(
      'readSnapshot',
      payload?.plant,
      String(payload?.resource),
    );
    if (!payload) {
      this.customLogger.error(`Payload is empty: ${payload}`, context);
      return;
    }

    const { family, plant, resource, ...resourceFamilyAssignData } = payload;

    try {
      // Split family values and filter out any empty strings
      let familyValues: Array<string> = [];

      if (family) {
        familyValues = family.includes(';')
          ? family.split(';').filter((f) => f.trim() !== '')
          : [family];
      } // Treat null family as an empty array or adjust logic based on your needs.
      const sqlStartTime = Date.now();

      await this.resourceFamilyAssignRepository.manager.transaction(
        async (transactionalEntityManager) => {
          await this.handleFamilyDeletions(
            resource,
            plant,
            familyValues,
            transactionalEntityManager,
          );
          const upsertPromises = familyValues.map(async (familyValue) => {
            let resourceFamilyAssign = await transactionalEntityManager.findOne(
              ResourceFamilyAssign,
              { where: { family: familyValue, plant, resource } },
            );

            if (resourceFamilyAssign) {
              // Update the entity's fields
              Object.assign(resourceFamilyAssign, resourceFamilyAssignData);
            } else {
              // Create a new entity
              resourceFamilyAssign = transactionalEntityManager.create(
                ResourceFamilyAssign,
                {
                  family: familyValue,
                  plant,
                  resource,
                  ...resourceFamilyAssignData,
                },
              );
            }

            // Save the entity (inserts if new, updates if existing)
            await transactionalEntityManager.save(resourceFamilyAssign);
          });

          await Promise.all(upsertPromises);
        },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'resourceFamilyAssign',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating Resource Family Assign: ${error.message}`,
        context,
      );
    }
  }
}

